"""Incremental People <> Locations relationship sync built on Company links.

The sync is designed so the paper trail of who is associated to which
company/locations can never be silently lost:

- State and checkpoint files are written atomically (temp + fsync + rename).
- Every attempted update (success, dry-run preview, or failure) is appended
  to a JSONL audit log.
- The incremental timestamp only advances after a fully successful, non-dry
  run; failures leave the window open so the next run retries it. Retries
  are cheap and idempotent because people who already have all company
  locations are skipped.
"""

import os
from typing import Any, Dict, List, Optional, Set

from .client import Client
from .utils import (
    append_audit_entry,
    build_relationship_value,
    extract_linked_record_ids,
    extract_record_id,
    get_first_value,
    load_json_state,
    normalize_attio_timestamp,
    save_json_state,
)


def get_recently_modified_people(
    client: Client,
    people_object: str,
    last_run: Optional[str],
    page_size: int,
) -> Set[str]:
    """Get people IDs that were created or updated since last run."""
    people_ids: Set[str] = set()

    if not last_run:
        print("No previous run found - this will process all people initially")
        for person in client.paginate_records(people_object, page_size=page_size):
            record_id = extract_record_id(person)
            if record_id:
                people_ids.add(record_id)
        return people_ids

    last_run_ts = normalize_attio_timestamp(last_run)
    last_run_date = last_run_ts[:10]

    # Attio filter operators are prefixed (e.g. $gte, $lt).
    created_filter = {"filter": {"created_at": {"$gte": last_run_ts}}}

    # Resolve a valid "updated" field from the object's attributes.
    # `updated_at` is not guaranteed to exist in every workspace.
    updated_filter = None
    updated_field_name = None
    try:
        attrs = client.list_attributes("objects", people_object).get("data", [])
        attrs_by_slug = {
            attr.get("api_slug"): (attr.get("type") or "").lower()
            for attr in attrs
            if attr.get("api_slug")
        }
        for candidate in ("updated_at", "last_updated_at", "date_last_updated"):
            if candidate in attrs_by_slug:
                updated_field_name = candidate
                if attrs_by_slug[candidate] == "date":
                    updated_filter = {
                        "filter": {candidate: {"value": {"$gte": last_run_date}}}
                    }
                else:
                    updated_filter = {"filter": {candidate: {"$gte": last_run_ts}}}
                break
    except Exception as e:
        print(f"Warning: Failed to inspect People attributes for updated-field: {e}")

    print(f"Fetching people created since {last_run_ts}")
    try:
        for person in client.paginate_records(
            people_object, payload=created_filter, page_size=page_size
        ):
            record_id = extract_record_id(person)
            if record_id:
                people_ids.add(record_id)
    except Exception as e:
        print(f"Warning: Failed to filter by created_at: {e}")

    if updated_filter and updated_field_name:
        print(
            f"Fetching people updated since {last_run_ts} using '{updated_field_name}'"
        )
        try:
            for person in client.paginate_records(
                people_object, payload=updated_filter, page_size=page_size
            ):
                record_id = extract_record_id(person)
                if record_id:
                    people_ids.add(record_id)
        except Exception as e:
            print(f"Warning: Failed to filter by {updated_field_name}: {e}")
    else:
        print(
            "No supported updated-field found (checked: updated_at, last_updated_at, "
            "date_last_updated). Continuing with created_at filter only."
        )

    print(f"Found {len(people_ids)} people modified since last run")
    return people_ids


def collect_target_companies(
    client: Client,
    company_object: str,
    company_people_attr: str,
    company_locations_attr: str,
    target_people_ids: Set[str],
    page_size: int,
    checkpoint_file: Optional[str] = None,
) -> Dict[str, Dict[str, Any]]:
    """Single scan over companies collecting the data needed for updates.

    Returns {company_id: {"name", "people": [...], "locations": [...]}} for
    every company linked to a target person. Capturing people/locations here
    avoids a second full pagination pass over all companies.
    """
    companies: Dict[str, Dict[str, Any]] = {}
    companies_seen = 0
    scan_offset = 0

    # Resume from checkpoint if available. Offset-based resume assumes the
    # company ordering is stable between the crash and the retry; a company
    # missed at a shifted boundary is picked up by the next incremental run.
    if checkpoint_file:
        checkpoint = load_json_state(checkpoint_file)
        if checkpoint.get("companies") is not None:
            companies = checkpoint["companies"]
            companies_seen = checkpoint.get("companies_seen", 0)
            scan_offset = checkpoint.get("offset", 0)
            print(
                f"Resuming from checkpoint: {companies_seen} companies scanned, "
                f"{len(companies)} relevant found, offset {scan_offset}"
            )

    def _write_checkpoint(error: Optional[str] = None) -> None:
        if not checkpoint_file:
            return
        data: Dict[str, Any] = {
            "companies_seen": companies_seen,
            "offset": scan_offset,
            "companies": companies,
        }
        if error:
            data["error"] = error
        save_json_state(checkpoint_file, data)

    try:
        for company in client.paginate_records(
            company_object,
            payload={"offset": scan_offset},
            page_size=page_size,
            delay_between_pages=0.2,
        ):
            companies_seen += 1
            scan_offset += 1

            if companies_seen % 500 == 0:
                _write_checkpoint()
            if companies_seen % 50 == 0:
                print(
                    f"Scanned {companies_seen} companies, found {len(companies)} relevant..."
                )

            company_values: Dict[str, Any] = company.get("values", {}) or {}
            person_ids = extract_linked_record_ids(
                company_values.get(company_people_attr, [])
            )
            if not any(pid in target_people_ids for pid in person_ids):
                continue

            company_id = extract_record_id(company)
            if not company_id:
                continue

            companies[company_id] = {
                "name": get_first_value(company_values, "name"),
                "people": person_ids,
                "locations": extract_linked_record_ids(
                    company_values.get(company_locations_attr, [])
                ),
            }
    except Exception as e:
        # Save checkpoint on error before raising
        _write_checkpoint(error=str(e))
        if checkpoint_file:
            print(
                f"💾 Checkpoint saved due to error. Progress: {companies_seen} companies scanned"
            )
        raise

    # Clear checkpoint on successful completion
    if checkpoint_file and os.path.exists(checkpoint_file):
        os.remove(checkpoint_file)

    print(f"Found {len(companies)} companies associated with recently modified people")
    return companies


def _person_display_name(person_values: Dict[str, Any], person_id: str) -> str:
    """Best-effort human-readable person name for logs and audit entries."""
    name_value = person_values.get("name")
    if isinstance(name_value, list) and name_value:
        first_item = name_value[0]
        if isinstance(first_item, dict):
            full = f"{first_item.get('first_name', '')} {first_item.get('last_name', '')}".strip()
            return full or first_item.get("value", person_id) or person_id
    return person_id


def sync_person_locations(
    client: Client,
    people_object: str,
    location_object: str,
    people_locations_attr: str,
    person_id: str,
    company_id: str,
    company_name: str,
    company_location_ids: List[str],
    dry_run: bool,
    audit_file: Optional[str],
) -> Optional[bool]:
    """Union a company's locations into one person's locations attribute.

    Returns True on update, False when no change needed, None on failure.
    """
    try:
        person = client.get_record(people_object, person_id)
    except Exception as e:
        print(f"‼️ Failed to fetch person {person_id}: {e}")
        append_audit_entry(
            audit_file,
            {
                "action": "fetch_failed",
                "person_id": person_id,
                "company_id": company_id,
                "company_name": company_name,
                "error": str(e),
            },
        )
        return None

    person_values: Dict[str, Any] = person.get("data", {}).get("values", {}) or {}
    person_name = _person_display_name(person_values, person_id)
    existing_ids = set(
        extract_linked_record_ids(person_values.get(people_locations_attr, []))
    )

    if existing_ids.issuperset(company_location_ids):
        return False

    desired_ids = list(existing_ids.union(company_location_ids))
    added_ids = sorted(set(company_location_ids) - existing_ids)
    audit_base = {
        "person_id": person_id,
        "person_name": person_name,
        "company_id": company_id,
        "company_name": company_name,
        "existing_location_ids": sorted(existing_ids),
        "added_location_ids": added_ids,
    }

    if dry_run:
        print(
            f"DRY-RUN: Would update {person_name} ({people_object}/{person_id}) set "
            f"'{people_locations_attr}' with {len(desired_ids)} locations "
            f"(adding {len(added_ids)})"
        )
        append_audit_entry(audit_file, {"action": "dry_run", **audit_base})
        return True

    payload = {
        "data": {
            "values": {
                people_locations_attr: build_relationship_value(
                    desired_ids, location_object
                )
            }
        }
    }
    try:
        client.update_record(people_object, person_id, payload)
        print(
            f"✅ Updated {person_name} ({person_id}) with {len(added_ids)} new locations"
        )
        append_audit_entry(audit_file, {"action": "updated", **audit_base})
        return True
    except Exception as e:
        print(f"‼️ Failed to update {people_object}/{person_id} for locations: {e}")
        append_audit_entry(
            audit_file, {"action": "update_failed", "error": str(e), **audit_base}
        )
        return None
